-- Public technical-question metadata only. Reference answers are not copied.
create table if not exists public.interview_technical_sheets (
  slug text primary key, title text not null, group_name text not null,
  source_url text not null, question_count integer not null check (question_count>=0),
  position integer not null
);
create table if not exists public.interview_technical_questions (
  sheet_slug text not null references public.interview_technical_sheets(slug) on delete cascade,
  question_id text not null references public.interview_questions(id),
  position integer not null, primary key(sheet_slug,position)
);
create index if not exists interview_technical_question_id_idx on public.interview_technical_questions(question_id);
alter table public.interview_technical_sheets enable row level security;
alter table public.interview_technical_questions enable row level security;
create policy interview_technical_sheets_read on public.interview_technical_sheets for select to anon,authenticated using (true);
create policy interview_technical_questions_read on public.interview_technical_questions for select to anon,authenticated using (true);
grant select on public.interview_technical_sheets,public.interview_technical_questions to anon,authenticated;

on conflict do nothing;

